m"><input class="wide" name="title" id="planTitle" placeholder="Plan title"><input name="projectedCovers" id="projectedCovers" type="number" min="0" placeholder="Projected covers"><input name="demandMultiplier" id="demandMultiplier" type="number" min="0.25" max="4" step="0.05" placeholder="Demand multiplier"><textarea class="wide" name="notes" id="planNotes" placeholder="Manager notes, events, unusual demand..."></textarea><?php if($canManage):?><button class="btn dark" type="submit">Save settings</button><button class="btn" type="button" id="closePlan">Close plan</button><?php endif;?></form></section><section class="panel status-box"><h3>How Gelato is thinking</h3><p id="thinking">Historical prep baselines use completed or verified prep tasks. Same-weekday samples are preferred; all-day history is only used as a lower-confidence fallback. Recipe-linked forecasts compare proposed batches with current inventory and pars.</p></section><section class="panel"><div class="panel-head"><div><h2>Add prep item</h2><p>Add directly to this plan and the canonical employee task list.</p></div></div><?php if($canManage):?><form class="form" id="taskForm"><input class="wide" name="title" placeholder="Prep item" required><input name="quantity" type="number" step="0.001" placeholder="Quantity"><input name="unit" placeholder="Unit"><input name="station" placeholder="Station"><select name="priority"><option value="normal">Normal</option><option value="high">High</option><option value="critical">Critical</option><option value="low">Low</option></select><button class="btn dark" type="submit">Add to prep list</button></form><?php else:?><div class="empty">Your role can view this plan but cannot change it.</div><?php endif;?></section><section class="panel"><div class="panel-head"><div><h2>Plan event trail</h2><p>Append-only plan activity.</p></div></div><div class="history" id="planEvents"></div></section></aside></section></main><div class="toast" id="toast"></div><script>window.PREP_I